 <div class="toast" id="toast">Signal shard collected</div>
 <section class="overlay" id="overlay"><div class="panel"><div class="eyebrow" id="overEyebrow">A NEW FLIGHT PATH</div><h1 id="overTitle">NEON<span>TIDES</span></h1><p class="subtitle" id="overCopy">Thread the storm-lit canyons of Sector 07. Catch five signal shards and reach the beacon before the tide closes in.</p><div class="chips" id="chips"><div class="chip">SPACE / TAP <b>· FLAP</b></div><div class="chip">SHIFT / ✳ <b>· SLIPSTREAM</b></div></div><button class="primary" id="startBtn">BEGIN FLIGHT&nbsp; →</button><div class="hint" id="hint">A fresh run starts with a charged slipstream.</div></div></section>
 </main>
 <script>
+(()=>{
+const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
+const $=id=>document.getElementById(id);
+const overlay=$('overlay'),hud=$('hud'),ability=$('ability'),pulseBtn=$('pulseBtn');
+let W=innerWidth,H=innerHeight,DPR=1,last=0,state='title',muted=false,audio=null;
+let cam=0,score=0,shardCount=0,time=0,worldSpeed=218,pulseTime=0,pulseReady=true,shake=0;
+let player, gates=[],particles=[],stars=[],clouds=[],backgroundTime=0;
+const GOAL=5,END_DISTANCE=10500,TAU=Math.PI*2;
+function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);seedSky()}
+function seedSky(){stars=Array.from({length:Math.max(28,Math.floor(W*H/13000))},()=>({x:Math.random()*W,y:Math.random()*H*.77,r:Math.random()*1.5+.25,a:.18+Math.random()*.55,phase:Math.random()*TAU}));clouds=Array.from({length:8},(_,i)=>({x:i*W/4+Math.random()*W/4,y:H*(.12+Math.random()*.58),s:.5+Math.random()*1.3,phase:Math.random()*TAU}))}
+addEventListener('resize',resize,{passive:true});resize();
+function audioCtx(){if(!audio)try{audio=new(window.AudioContext||window.webkitAudioContext)()}catch{}if(audio?.state==='suspended')audio.resume();return audio}
+function tone(freq=500,dur=.1,type='sine',vol=.035){if(muted)return;const ac=audioCtx();if(!ac)return;const o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+dur);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+dur)}
+function setOverlay(kind){overlay.classList.remove('hidden');$('chips').style.display=kind==='title'?'flex':'none';$('hint').style.display=kind==='title'?'block':'none';if(kind==='title'){$('overEyebrow').textContent='A NEW FLIGHT PATH';$('overTitle').innerHTML='NEON<span>TIDES</span>';$('overCopy').textContent='Thread the storm-lit canyons of Sector 07. Catch five signal shards and reach the beacon before the tide closes in.';$('startBtn').textContent='BEGIN FLIGHT  →';$('hint').textContent='A fresh run starts with a charged slipstream.'}else if(kind==='pause'){$('overEyebrow').textContent='FLIGHT PAUSED';$('overTitle').innerHTML='TAKE A<span>BREATH</span>';$('overCopy').textContent='The canyon can wait. Your run is safely paused.';$('startBtn').textContent='RESUME FLIGHT  →'}else if(kind==='win'){$('overEyebrow').textContent='SECTOR 07 · CLEARED';$('overTitle').innerHTML='BEACON<span>REACHED</span>';$('overCopy').textContent=`${score} meters flown · ${shardCount} signal shards recovered. The Neon Tides are yours.`;$('startBtn').textContent='FLY AGAIN  →'}else{$('overEyebrow').textContent=shardCount>=GOAL?'SIGNAL LOCKED':'FLIGHT ENDED';$('overTitle').innerHTML=shardCount>=GOAL?'SO CLOSE<span>TO THE LIGHT</span>':'LOST IN THE<span>TIDES</span>';$('overCopy').textContent=shardCount>=GOAL?`You found all five shards, but the beacon slipped away at ${score}m. One more run?`:`${score}m flown · ${shardCount} of ${GOAL} shards recovered. The storm is still out there.`;$('startBtn').textContent='TRY AGAIN  →'} }
+function startGame(){audioCtx();cam=0;score=0;shardCount=0;time=0;pulseTime=0;pulseReady=true;shake=0;worldSpeed=Math.min(250,218+Math.random()*3);gates=[];particles=[];player={x:W*.255,y:H*.48,vy:0,r:13,rot:0,trail:[]};let gx=W+280;for(let i=0;i<18;i++){gates.push(makeGate(gx,i));gx+=390+Math.random()*100}hud.classList.add('visible');ability.classList.add('visible');overlay.classList.add('hidden');state='playing';updateHud()}
+function makeGate(x,i){const margin=Math.max(65,H*.14),top=margin+Math.random()*(H*.26),gap=Math.min(206,Math.max(170,H*.34));return{x,baseY:top+gap/2+(H-top-gap)*(Math.random()*.55),gap,amp:Math.min(30,H*.055)+Math.random()*10,phase:Math.random()*TAU,speed:.7+Math.random()*.6,shard:true,passed:false,seed:i}}
+function gateY(g){return g.baseY+Math.sin(time*g.speed+g.phase)*g.amp}
+function flap(){if(state!=='playing')return;player.vy=Math.min(player.vy,100)-390;player.rot=-.35;tone(420,.065,'triangle',.022);emit(player.x-10,player.y,3,'#9bfff0')}
+function activatePulse(){if(state!=='playing'||!pulseReady)return;pulseReady=false;pulseTime=1.15;player.vy=Math.min(player.vy,10);tone(730,.19,'sine',.055);for(let i=0;i<18;i++)emit(player.x,player.y,1,'#68f5e1');toast('SLIPSTREAM ENGAGED · LIFT GRAVITY FLIPS');updateHud()}
+function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),1350)}
+function updateHud(){$('distance').textContent=Math.floor(cam/10);$('shardCount').textContent=`${shardCount} / ${GOAL}`;$('progress').style.width=Math.min(100,cam/END_DISTANCE*100)+'%';$('shards').innerHTML=Array.from({length:GOAL},(_,i)=>`<i class="shard-dot ${i<shardCount?'on':''}"></i>`).join('');pulseBtn.classList.toggle('ready',pulseReady);pulseBtn.classList.toggle('spent',!pulseReady);$('pulseLabel').textContent=pulseReady?'READY':pulseTime>0?'LIFT':'RECHARGING'}
+function emit(x,y,n,color){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.7)*140,vy:(Math.random()-.5)*140,life:.25+Math.random()*.55,max:.8,size:1.5+Math.random()*3,color})}
+function gameOver(win=false){if(state!=='playing')return;state=win?'win':'over';shake=win?0:8;setOverlay(win?'win':'over');tone(win?880:160,.45,win?'sine':'triangle',.05);}
+function collideCircleRect(cx,cy,r,x,y,w,h){const nx=Math.max(x,Math.min(cx,x+w)),ny=Math.max(y,Math.min(cy,y+h));return (cx-nx)**2+(cy-ny)**2<r*r}

