function collideCircleRect(cx,cy,r,x,y,w,h){const nx=Math.max(x,Math.min(cx,x+w)),ny=Math.max(y,Math.min(cy,y+h));return (cx-nx)**2+(cy-ny)**2<r*r}
function update(dt){backgroundTime+=dt;if(state!=='playing')return;time+=dt;cam+=worldSpeed*dt;score=Math.floor(cam/10);if(pulseTime>0){pulseTime=Math.max(0,pulseTime-dt);if(!pulseTime)toast('SLIPSTREAM SPENT · FIND A SHARD');}player.vy+=(pulseTime>0?-675:1020)*dt;player.vy=Math.max(-390,Math.min(530,player.vy));player.y+=player.vy*dt;player.rot+=(Math.max(-.55,Math.min(.7,player.vy/620))-player.rot)*Math.min(1,dt*7);player.trail.push({x:player.x-9,y:player.y});if(player.trail.length>8)player.trail.shift();
for(const g of gates){const sx=g.x-cam,cy=gateY(g),gapTop=cy-g.gap/2,gapBottom=cy+g.gap/2;if(sx<-70&&!g.passed){g.passed=true;if(shardCount>=GOAL&&cam>=END_DISTANCE)gameOver(true)}if(sx<W+200&&sx>-50){if(collideCircleRect(player.x,player.y,player.r,sx,gapTop-600,32,600)||collideCircleRect(player.x,player.y,player.r,sx,gapBottom,32,600)){gameOver(false);return}if(g.shard&&Math.abs(player.x-(sx+16))<23&&Math.abs(player.y-cy)<25){g.shard=false;shardCount++;pulseReady=true;emit(player.x,player.y,24,'#ffdf91');tone(920,.12,'sine',.045);setTimeout(()=>tone(1240,.16,'sine',.035),70);toast(shardCount>=GOAL?'FIVE SHARDS · BEACON UNLOCKED':'SIGNAL SHARD RECOVERED · SLIPSTREAM CHARGED');updateHud()}}}
if(player.y-player.r<7||player.y+player.r>H-7){gameOver(false);return}for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt;if(p.life<=0)particles.splice(i,1)}shake=Math.max(0,shake-dt*20);updateHud();if(cam>=END_DISTANCE&&shardCount>=GOAL)gameOver(true);else if(cam>=END_DISTANCE+3200)gameOver(false);if(gates.length&&gates[gates.length-1].x-cam<W*2.7){const lastGate=gates[gates.length-1];gates.push(makeGate(lastGate.x+390+Math.random()*110,lastGate.seed+1))}while(gates.length&&gates[0].x-cam<-150)gates.shift()}
function roundedRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function drawSky(){const grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,'#071326');grad.addColorStop(.52,'#102b48');grad.addColorStop(1,'#153f56');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);const glow=ctx.createRadialGradient(W*.73,H*.33,3,W*.73,H*.33,H*.76);glow.addColorStop(0,'#19778038');glow.addColorStop(.5,'#16495b19');glow.addColorStop(1,'#07132600');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
for(const s of stars){let x=(s.x-cam*.012+W*2)%(W*1.35);ctx.globalAlpha=s.a*(.78+.22*Math.sin(backgroundTime*1.5+s.phase));ctx.fillStyle='#d5fff9';ctx.beginPath();ctx.arc(x,s.y,s.r,0,TAU);ctx.fill()}ctx.globalAlpha=1;
// distant layered canyon silhouettes
for(let layer=0;layer<3;layer++){const parallax=[.025,.055,.095][layer],base=H*(.72+layer*.12),amp=H*(.09+layer*.018),spacing=W*.42;ctx.beginPath();ctx.moveTo(0,H);for(let x=-spacing;x<W+spacing;x+=12){const worldX=x+cam*parallax;const yy=base-amp*(.48+.34*Math.sin(worldX*.003+layer*2)+.18*Math.sin(worldX*.008+layer));ctx.lineTo(x,yy)}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=['#122b45','#12374b','#164253'][layer];ctx.fill();ctx.strokeStyle=['#5ce5cf12','#5ce5cf18','#73ffe321'][layer];ctx.lineWidth=1;ctx.stroke()}
// floating wisps
for(const c of clouds){let x=(c.x-cam*(.12+c.s*.025)+W*2)%(W*1.35)-W*.15;const y=c.y+Math.sin(backgroundTime*.2+c.phase)*8;ctx.globalAlpha=.035+c.s*.018;ctx.fillStyle='#b8fff0';ctx.beginPath();ctx.ellipse(x,y,58*c.s,9*c.s,-.08,0,TAU);ctx.fill();ctx.globalAlpha=1}
// luminous tide horizon
const hy=H*.81;ctx.save();ctx.globalAlpha=.23;ctx.strokeStyle='#52f1d2';ctx.lineWidth=1;for(let i=0;i<5;i++){const y=hy+i*13;ctx.beginPath();for(let x=0;x<=W;x+=10){const wave=y+Math.sin((x+cam*.18)*.012+i)*3; x===0?ctx.moveTo(x,wave):ctx.lineTo(x,wave)}ctx.stroke()}ctx.restore()}
function drawGate(g){const x=g.x-cam,cy=gateY(g),top=cy-g.gap/2,bottom=cy+g.gap/2,w=34;if(x<-70||x>W+70)return;const hue='#67f0de';ctx.save();ctx.shadowColor=hue;ctx.shadowBlur=15;const grad=ctx.createLinearGradient(x,0,x+w,0);grad.addColorStop(0,'#194d61');grad.addColorStop(.45,'#246b78');grad.addColorStop(1,'#16465a');ctx.fillStyle=grad;ctx.fillRect(x,0,w,top);ctx.fillRect(x,bottom,w,H-bottom);ctx.shadowBlur=0;ctx.fillStyle='#b3fff0';ctx.fillRect(x-2,top-2,w+4,3);ctx.fillRect(x-2,bottom-1,w+4,3);ctx.fillStyle='#68f5e1';for(let j=14;j<top-12;j+=28)ctx.fillRect(x+8,j,2,7);for(let j=bottom+16;j<H-14;j+=28)ctx.fillRect(x+8,j,2,7);
// tiny turbine-like cap
ctx.strokeStyle='#8effe9aa';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x+w/2,top-2);ctx.lineTo(x+w/2,top-11);ctx.arc(x+w/2,top-13,3,0,TAU);ctx.stroke();
if(g.shard){const bob=Math.sin(time*2.7+g.phase)*5,sx=x+w/2,sy=cy+bob;ctx.save();ctx.translate(sx,sy);ctx.rotate(time*1.2+g.phase);ctx.shadowColor='#ffe28c';ctx.shadowBlur=18;ctx.fillStyle='#ffe8a3';ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(7,0);ctx.lineTo(0,9);ctx.lineTo(-7,0);ctx.closePath();ctx.fill();ctx.restore();ctx.strokeStyle='#fff0bb66';ctx.beginPath();ctx.arc(sx,sy,15+Math.sin(time*3+g.phase)*2,0,TAU);ctx.stroke()}
ctx.restore()}
function drawPlayer(){if(!player)return;ctx.save();for(let i=0;i<player.trail.length;i++){const p=player.trail[i];ctx.globalAlpha=(i/player.trail.length)*.22;ctx.fillStyle=pulseTime>0?'#62f2e3':'#d3fff2';ctx.beginPath();ctx.arc(p.x,p.y,(i/player.trail.length)*7,0,TAU);ctx.fill()}ctx.globalAlpha=1;ctx.translate(player.x,player.y);ctx.rotate(player.rot);if(pulseTime>0){ctx.strokeStyle='#68f5e1';ctx.globalAlpha=.65;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,22+Math.sin(time*16)*3,0,TAU);ctx.stroke();ctx.globalAlpha=1;ctx.shadowColor='#68f5e1';ctx.shadowBlur=22}ctx.fillStyle='#f0fff6';ctx.strokeStyle='#82ffe7';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-15,1);ctx.quadraticCurveTo(-3,-8,12,-2);ctx.lineTo(19,1);ctx.lineTo(9,5);ctx.quadraticCurveTo(-5,9,-15,1);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#62ebd5';ctx.beginPath();ctx.moveTo(-4,1);ctx.lineTo(-13,-12);ctx.lineTo(4,-3);ctx.closePath();ctx.fill();ctx.fillStyle='#ffdc8a';ctx.beginPath();ctx.moveTo(18,0);ctx.lineTo(24,2);ctx.lineTo(18,4);ctx.closePath();ctx.fill();ctx.fillStyle='#11233a';ctx.beginPath();ctx.arc(7,-1,1.4,0,TAU);ctx.fill();ctx.restore()}

